// claudinite-growth task: prose-to-checks-sweep — mine a repo's EXISTING pack
// prose for always-testable rules the conversion missed and convert the strongest
// ones (per-project-scheduling redesign). A per-repo task: every repo declaring the
// growth pack sweeps its OWN packs. Which pack paths it works is a config setting,
// `pack_paths`, defaulting to the repo's own local packs; Claudinite itself sets it
// to ALSO include its core `packs/` (projects are not expected to improve core canon
// packs — only Claudinite does). The method is owned by the prose-to-checks skill.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The repo's own capture surface — a consumer improves only its LOCAL packs.
const DEFAULT_PACK_PATHS = ['.claudinite/local/packs'];

export default {
  id: 'prose-to-checks-sweep',
  frequency: 'weekly',                   // works the STANDING backlog a slice at a time — see the cadence note below
  precondition_signals: [],              // the backlog is standing prose, not a windowed signal
  agent_model: 'opus',                   // judging convertibility and authoring checks + fixtures is heavy judgment
  expected_outcome: 'open-pr',           // converts prose to checks in an owner-approved PR (a check can break CI, so it's reviewed)
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading the packs + authoring a check with fixtures — generous bound

  // WEEKLY, not daily. Freshly written prose no longer waits for this task at all:
  // growth-extract runs the prose-to-checks skill over its OWN additions as the last
  // step of every capture run, so a convertible rule is converted the night it is
  // learned. What is left here is the standing backlog — prose that has already
  // survived at least one upgrade pass — and that set changes on a weekly clock, not
  // a daily one. Daily re-read the same dry corpus with an opus dispatch and an
  // owner-gated PR nobody was waiting on.
  precondition(_signals, config) {
    const paths = Array.isArray(config?.pack_paths) && config.pack_paths.length ? config.pack_paths : DEFAULT_PACK_PATHS;
    return {
      run: true,
      reason: `weekly prose-to-checks backlog sweep over ${paths.join(', ')} (no-ops cheaply when dry)`,
      context: [`Pack paths to sweep (work ONLY these; never a read-only mounted canon pack under .claudinite/shared/): ${paths.join(', ')}.`],
    };
  },
};

// LaughCounter's general local pack: the working lessons about this repo that
// aren't about the on-device-privacy boundary (that one has its own pack). It
// carries prose only for now.
//
// A local pack: declared by hand as `local/laughcounter`, never fingerprinted
// (detect/marker null).
export default {
  id: 'laughcounter',
  ruleRoutingGuidance: {
    belongs:
      "LaughCounter's general working lessons about this repo — its build, macOS packaging and versioning, check authoring, Claudinite maintenance findings",
    excludes:
      "the on-device privacy boundary (on-device-privacy) and the microphone's lifecycle (macos-audio)",
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [],
};

[
  {
    "id": "macos-audio/no-sudden-termination",
    "severity": "blocking",
    "failureMessage": "sudden termination lets logout SIGKILL the app past every teardown path, abandoning the input tap's IOProc on the device — the state that wedges a USB mic until it is re-plugged",
    "scanFiles": "/^mac\\/Resources\\/.*\\.plist$/",
    "matchLines": [
      {
        "match": "/NSSupportsSuddenTermination/",
        "what": "the app's Info.plist declares NSSupportsSuddenTermination",
        "fix": "remove the key — the app must get the chance to remove its tap and stop the engine on the way out; weigh any launch cost against a wedged mic"
      }
    ]
  },
  {
    "id": "macos-audio/engine-construction-confined",
    "severity": "blocking",
    "failureMessage": "constructing an engine opens the default input and churns a hidden coreaudiod aggregate device — the one mechanism by which this app could plausibly wedge a mic",
    "scanFiles": "/^mac\\/Sources\\/.*\\.swift$/",
    "excludeFiles": "mac/Sources/LaughCounter/AudioHub.swift",
    "matchLines": [
      {
        "match": "/\\bAVAudioEngine\\s*\\(/",
        "what": "builds an AVAudioEngine outside mac/Sources/LaughCounter/AudioHub.swift",
        "fix": "ask AudioDiagnostics instead — hasUsableInput and inputAvailability answer from HAL queries that open no device; if capture is needed, route it through AudioHub, the engine's single owner"
      }
    ]
  }
]

[
  {
    "id": "on-device-privacy/no-network-client",
    "severity": "blocking",
    "failureMessage": "the product's headline promise is that the room's audio never leaves the machine — a client in the capture path is how that promise breaks",
    "scanFiles": "/^mac\\/Sources\\/.*\\.swift$/",
    "fix": "keep analysis on-device — drop the client; the app has no accepted egress, so adding one is a product decision that belongs in RULES.md first",
    "matchLines": [
      { "match": "/\\bURLSession\\b/", "what": "URLSession in the capture path" },
      { "match": "/\\bNSURLConnection\\b/", "what": "NSURLConnection in the capture path" },
      { "match": "/^\\s*import\\s+Network\\b/", "what": "the Network framework imported in the capture path" },
      { "match": "/\\bNWConnection\\b/", "what": "NWConnection in the capture path" }
    ]
  },
  {
    "id": "on-device-privacy/no-audio-persistence",
    "severity": "blocking",
    "failureMessage": "the product promise is that only derived metadata is kept and no audio is stored — a file-writing audio API in the capture path is how that promise breaks",
    "scanFiles": "/^mac\\/Sources\\/.*\\.swift$/",
    "fix": "keep audio out of persistence — drop the writer; deliberately adding audio storage (the v3 roadmap) is a product decision that belongs in RULES.md and the mic usage strings first",
    "matchLines": [
      { "match": "/\\bAVAudioFile\\s*\\(\\s*forWriting\\b/", "what": "AVAudioFile(forWriting:) in the capture path" },
      { "match": "/\\bAVAudioRecorder\\s*\\(/", "what": "AVAudioRecorder in the capture path" },
      { "match": "/\\bExtAudioFileCreateWithURL\\s*\\(/", "what": "ExtAudioFileCreateWithURL in the capture path" },
      { "match": "/\\bAudioFileCreateWithURL\\s*\\(/", "what": "AudioFileCreateWithURL in the capture path" }
    ]
  },
  {
    "id": "on-device-privacy/no-listener",
    "severity": "blocking",
    "failureMessage": "a listener exposes the laugh log to whatever can reach the port — reintroducing one is a decision about who may read the room, not a feature",
    "scanFiles": "/^mac\\/Sources\\/.*\\.swift$/",
    "fix": "drop the listener; a dashboard, metrics port or remote-control API needs the owner's sign-off, a loopback-only default and an auth/CSRF story in RULES.md first",
    "matchLines": [
      { "match": "/\\bNWListener\\b/", "what": "NWListener (a Network-framework listener) in the app" },
      { "match": "/\\bNSXPCListener\\b/", "what": "NSXPCListener in the app" },
      { "match": "/\\bCFSocket[A-Za-z]*\\s*\\(/", "what": "a CFSocket API in the app" },
      { "match": "/\\b(?:NS)?SocketPort\\b/", "what": "SocketPort in the app" },
      { "match": "/\\bsocket\\s*\\(/", "what": "socket(2) in the app" },
      { "match": "/^\\s*import\\s+(?:Vapor|NIO[A-Za-z]*|Swifter|Telegraph|Hummingbird|Kitura[A-Za-z]*|Perfect[A-Za-z]*|FlyingFox|Embassy|GCDWebServer|Criollo)\\b/", "what": "an embedded HTTP server framework imported in the app" }
    ]
  }
]

import inputNodeConfined from './input-node-confined.mjs';
import signalTeardownRouting from './signal-teardown-routing.mjs';
import swiftToolchainGate from './swift-toolchain-gate.mjs';

// The macOS microphone lifecycle, as a pack: AVAudioEngine, CoreAudio device
// state, and the sleep/wake and exit paths around them. LaughCounter holds a
// real mic open for hours and has repeatedly left one *wedged* — dead
// system-wide until re-plugged — so this is a technology domain with its own
// hard-won rules, none of which the canon shelf homes.
//
// The case history stays in `dev/procedures/mac-audio-lifecycle.md` (routed from
// the project CLAUDE.md); this pack carries the invariants and enforces the ones
// a scan can decide.
//
// A local pack: declared by hand as `local/macos-audio`, never
// fingerprinted (detect/marker null).
export default {
  id: 'macos-audio',
  ruleRoutingGuidance: {
    belongs:
      'holding a macOS microphone safely — AVAudioEngine and CoreAudio device lifecycle, sleep/wake and exit teardown, audio-arrival diagnostics',
    excludes:
      "the privacy boundary (on-device-privacy) and the repo's build, packaging and check-authoring lessons (laughcounter)",
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [inputNodeConfined, signalTeardownRouting, swiftToolchainGate],
};

// "Never open the device to ask a question about it" (#88), as a check on the
// *touch* rather than the construction: `engine.inputNode` may only be reached
// in `AudioHub`.
//
// Reading `inputNode` is not a property read. It creates the input node lazily,
// which opens the default input device and mints a hidden per-client aggregate
// device inside coreaudiod (`CADefaultDeviceAggregate-<pid>-<n>`); one measured
// outage ran that open/create/destroy cycle ~210 times over 3h40m against
// hardware that was not there. Cycling the device is the one mechanism by which
// this app could plausibly wedge a mic, so the cost of an answer is a property of
// the API you ask, not of how often you ask it. Availability questions go to
// `AudioDiagnostics`, which answers from `AudioObjectGetPropertyData` property
// queries that open nothing.
//
// Its sibling `engine-construction-confined` is NOT this check. That one bans
// `AVAudioEngine(` outside `AudioHub`, and a file that never constructs an engine
// can still be handed one:
//
//     func probeRate(engine: AVAudioEngine) -> Double {
//         engine.inputNode.inputFormat(forBus: 0).sampleRate
//     }
//
// opens the device and trips nothing (a fixture pins that gap — the repo's own
// rule is that "already covered by another check" is a claim you hand a violating
// file, not one you reason out).
//
// Comments are stripped before matching, because the sources discuss
// `engine.inputNode` at length in exactly the files that must not touch it —
// `AppDelegate` and `AudioDiagnostics` both explain the aggregate-device cost in
// a doc comment. Stripping is deliberately conservative: `//` that follows a
// colon is left alone so a `https://` URL is not mistaken for a comment.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

// The one file allowed to touch it. `AudioHub` owns the microphone: it
// materializes `inputNode` before `prepare()` (#72), installs and removes the
// tap, and reads the input format for `validatedFormat()`.
const OWNER = 'mac/Sources/LaughCounter/AudioHub.swift';

// A member access, not a mention: `engine.inputNode`, `self.engine.inputNode`.
const TOUCH = /\.inputNode\b/;

// Block comments first, then line comments — `//` only when it is not the tail of
// a `scheme://` URL. Newlines are preserved so reported line numbers stay true.
const stripComments = (text) => text
  .replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, ' '))
  .split('\n')
  .map((line) => line.replace(/(^|[^:])\/\/.*$/, '$1'))
  .join('\n');

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'macos-audio/input-node-confined',
  severity: 'blocking',
  description: 'Only AudioHub touches engine.inputNode — reading it opens the default input device (mac/Sources/)',
  doc: '.claudinite/local/packs/macos-audio/RULES.md',
  why: 'accessing inputNode materializes the input node, which opens the default input and churns a hidden coreaudiod aggregate device — the one mechanism by which this app could plausibly wedge a mic',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      if (file === OWNER) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = stripComments(text).split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        if (!TOUCH.test(lines[i])) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: i + 1,
          what: `reaches engine.inputNode outside ${OWNER} (${file})`,
          why: rule.why,
          fix: 'ask AudioDiagnostics instead — `hasUsableInput` / `inputAvailability` answer from HAL property queries that open no device; if the format or a tap really is needed, route it through AudioHub, the single owner of the engine lifecycle',
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;

